<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {Console,Row} from '../console';
import Icon from './Icon.vue';import OriginsList from './OriginsList.vue';
const props=defineProps<{c:Console}>();
const kind=ref('user'),source=ref(''),target=ref(''),assigned=ref<Row[]>([]),origins=ref<Row[]>([]),loading=ref(false);let revision=0;
watch(()=>props.c.s.refreshVersion,()=>{void load();});
const tabs=[{id:'user',title:'用户 → 角色',label:'为成员分配角色',icon:'users'},{id:'role',title:'角色 → 权限',label:'为角色配置直接权限',icon:'shield'},{id:'api',title:'权限 → API',label:'绑定后端接口资源',icon:'code'}];
const fromLabel=computed(()=>kind.value==='user'?'选择用户':kind.value==='role'?'选择角色':'选择前端权限');
const targetLabel=computed(()=>kind.value==='user'?'待分配角色':kind.value==='role'?'待授予权限':'待绑定 API');
const sources=computed(()=>kind.value==='user'?props.c.s.users:kind.value==='role'?props.c.s.roles:props.c.s.permissions);
const current=computed(()=>sources.value.find(r=>r.id===Number(source.value)));
const options=computed(()=>{let values=kind.value==='user'?props.c.s.roles:kind.value==='role'?props.c.s.permissions:props.c.s.resources;if(kind.value==='api')values=values.filter(r=>r.systemId===current.value?.systemId);return values.filter(r=>!assigned.value.some(a=>a.id===r.id)&&('enabled'in r?r.enabled:r.active));});
function route(id?:string|number){return kind.value==='user'?`/api/users/${source.value}/roles${id?'/'+id:''}`:kind.value==='role'?`/api/roles/${source.value}/permissions${id?'/'+id:''}`:`/api/permissions/${source.value}/resources${id?'/'+id:''}`;}
watch(kind,()=>{source.value='';target.value='';});
watch([kind,source],()=>{target.value='';void load();});
async function load(){const version=++revision;assigned.value=[];origins.value=[];if(!source.value)return;loading.value=true;try{const list=await props.c.api(route());const details=kind.value==='api'?[]:await props.c.api(kind.value==='user'?`/api/users/${source.value}/permission-origins`:`/api/roles/${source.value}/effective-permissions`);if(version===revision){assigned.value=list;origins.value=details;}}catch(e){if(version===revision)props.c.message((e as Error).message,true);}finally{if(version===revision)loading.value=false;}}
async function add(){if(!source.value||!target.value)return;await props.c.run(async()=>{await props.c.api(route(target.value),'PUT');target.value='';await load();props.c.message('授权关系已保存');});}
async function remove(row:Row){if(!await props.c.ask('撤回直接关系',`确认撤回“${current.value?.displayName||current.value?.name}”与“${row.name}”之间的关系？其他角色或继承路径提供的权限会保留。`))return;await props.c.run(async()=>{await props.c.api(route(row.id),'DELETE');await load();props.c.message('直接关系已撤回');});}
</script>
<template><div class="workflow-tabs" role="tablist" aria-label="授权类型"><button v-for="(tab,index) in tabs" :id="'tab-'+tab.id" :key="tab.id" :class="{selected:kind===tab.id}" role="tab" :aria-selected="kind===tab.id" aria-controls="grant-panel" :disabled="c.s.busy" @click="kind=tab.id"><span class="step-number">0{{index+1}}</span><div><strong>{{tab.title}}</strong><small>{{tab.label}}</small></div><Icon :name="tab.icon"/></button></div><section id="grant-panel" class="panel grant-panel" role="tabpanel" :aria-labelledby="'tab-'+kind"><div class="grant-setup"><div class="section-heading"><div><p class="eyebrow">CONFIGURE ACCESS</p><h2>建立{{kind==='api'?'资源绑定':'授权关系'}}</h2></div></div><p class="muted">{{kind==='user'?'用户将获得这些角色的有效权限，包括角色继承带来的权限。':kind==='role'?'此处维护直接授权；继承权限请在角色继承中查看来源。':'前端权限与接口独立建模，只能绑定同一应用下的 API。'}}</p><label>{{fromLabel}}<select :aria-label="fromLabel" v-model="source" :disabled="c.s.busy"><option value="">{{fromLabel}}</option><option v-for="item in sources" :key="item.id" :value="item.id">{{item.displayName||item.name}} · {{item.username||item.code}}</option></select></label><div v-if="kind==='user'&&c.s.userTotal>25" class="picker-pager"><button :disabled="c.s.busy||c.s.pickerPage===0" @click="source='';c.run(()=>c.picker(c.s.pickerPage-1))">上一批</button><small>第 {{c.s.pickerPage+1}} 批 · 共 {{c.s.userTotal}} 人</small><button :disabled="c.s.busy||(c.s.pickerPage+1)*25>=c.s.userTotal" @click="source='';c.run(()=>c.picker(c.s.pickerPage+1))">下一批</button></div><label>{{targetLabel}}<select :aria-label="targetLabel" v-model="target" :disabled="!source||loading||c.s.busy"><option value="">{{source?'请选择可用资源':'请先选择左侧对象'}}</option><option v-for="item in options" :key="item.id" :value="item.id">{{item.name}}{{item.code?' · '+item.code:item.method?' · '+item.method+' '+item.path:''}}</option></select></label><button class="primary wide" :disabled="!source||!target||loading||c.s.busy" @click="add"><Icon name="plus"/>{{kind==='api'?'保存绑定':'保存授权'}}</button><p class="hint"><Icon name="info"/>{{kind==='api'?'页面入口可见不等于接口可调用，还需完整的用户、角色与权限关系。':'保存后下一次请求即按新关系检查，无需重新登录。'}}</p></div><div class="grant-results"><div class="section-heading"><h2>已建立的直接关系</h2><span class="count">{{assigned.length}}</span></div><p v-if="loading" class="loading-line">正在读取关系…</p><div v-else-if="!source||!assigned.length" class="empty"><Icon name="link" :size="35"/><h3>{{source?'暂未建立直接关系':'先选择一个对象'}}</h3><p>{{source?'从左侧选择可用资源，建立第一条关系。':'选择后，可在这里查看并撤回已有关系。'}}</p></div><article v-for="row in assigned" v-else :key="row.id" class="assigned-row"><span class="resource-icon"><Icon :name="kind==='user'?'shield':kind==='role'?'layers':'code'"/></span><div><strong>{{row.name}}</strong><code>{{row.code||row.method+' '+row.path}}</code></div><span class="badge neutral">直接关系</span><button class="text-danger" :disabled="c.s.busy" @click="remove(row)">撤回</button></article></div></section><section v-if="source&&kind!=='api'" class="panel"><div class="section-heading"><div><h2>最终有效权限</h2><p class="muted">{{current?.displayName||current?.name}}通过所有有效角色及继承路径获得的权限。</p></div><span class="count">{{origins.length}}</span></div><OriginsList :items="origins" :roles="c.s.roles"/></section></template>
